CREATE DATABASE IF NOT EXISTS school_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE school_management;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(100) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','teacher','class_teacher','head_teacher','parent','student') NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE teachers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,phone VARCHAR(30),is_class_teacher TINYINT(1) DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE head_teachers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,level ENUM('primary','secondary') NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE classes(id INT AUTO_INCREMENT PRIMARY KEY,class_name VARCHAR(80) NOT NULL,level ENUM('primary','secondary') NOT NULL,class_teacher_id INT NULL,capacity INT DEFAULT 50,FOREIGN KEY(class_teacher_id) REFERENCES teachers(id) ON DELETE SET NULL);
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY,course_name VARCHAR(100) NOT NULL,course_code VARCHAR(30) UNIQUE NOT NULL);
CREATE TABLE teacher_courses(id INT AUTO_INCREMENT PRIMARY KEY,teacher_id INT NOT NULL,course_id INT NOT NULL,class_id INT NOT NULL,UNIQUE KEY assignment(teacher_id,course_id,class_id),FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE);
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,admission_number VARCHAR(40) UNIQUE NOT NULL,class_id INT NOT NULL,profile_picture VARCHAR(255),current_class_id INT,promotion_status ENUM('current','promoted','demoted','skipped','held_back') DEFAULT 'current',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(current_class_id) REFERENCES classes(id));
CREATE TABLE parents(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE parent_students(parent_id INT NOT NULL,student_id INT NOT NULL,PRIMARY KEY(parent_id,student_id),FOREIGN KEY(parent_id) REFERENCES parents(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE grades(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,teacher_id INT NOT NULL,class_id INT NOT NULL,score DECIMAL(5,2) NOT NULL,grade CHAR(1) NOT NULL,academic_term VARCHAR(30) NOT NULL,academic_year YEAR NOT NULL,is_approved TINYINT(1) DEFAULT 0,approved_by INT NULL,approved_at DATETIME NULL,UNIQUE KEY one_grade(student_id,course_id,academic_term,academic_year),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(teacher_id) REFERENCES teachers(id),FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE grade_summaries(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,class_id INT NOT NULL,academic_term VARCHAR(30) NOT NULL,academic_year YEAR NOT NULL,total_courses INT,total_score DECIMAL(8,2),average_score DECIMAL(5,2),position INT,is_released TINYINT(1) DEFAULT 0,released_date DATETIME,UNIQUE KEY summary(student_id,academic_term,academic_year),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,class_id INT NOT NULL,class_teacher_id INT NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','late','excused') NOT NULL,remarks VARCHAR(255),UNIQUE KEY one_day(student_id,attendance_date),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(class_teacher_id) REFERENCES teachers(id));
CREATE TABLE performance_reports(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,reporter_id INT NOT NULL,academic_term VARCHAR(30) NOT NULL,academic_year YEAR NOT NULL,performance_rating ENUM('excellent','good','average','poor') NOT NULL,comments TEXT NOT NULL,recommendation ENUM('promote','demote','skip_class','hold_back','maintain') NOT NULL,report_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(reporter_id) REFERENCES users(id));
CREATE TABLE promotion_records(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,from_class_id INT NOT NULL,to_class_id INT NOT NULL,promotion_type ENUM('promote','demote','skip','hold_back','maintain') NOT NULL,academic_year YEAR NOT NULL,admin_remarks TEXT,approved_by INT NOT NULL,approved_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(from_class_id) REFERENCES classes(id),FOREIGN KEY(to_class_id) REFERENCES classes(id),FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE violation_reports(id INT AUTO_INCREMENT PRIMARY KEY,head_teacher_id INT NOT NULL,reported_user_id INT NULL,report_type VARCHAR(40) NOT NULL,severity ENUM('low','medium','high') DEFAULT 'medium',description TEXT NOT NULL,status ENUM('pending','reviewed','resolved') DEFAULT 'pending',admin_remarks TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(head_teacher_id) REFERENCES head_teachers(id),FOREIGN KEY(reported_user_id) REFERENCES users(id) ON DELETE SET NULL);
